import json
from pathlib import Path

ui_dir = Path('uigames/hero_adventure/ui')
frame_defs = [
    {'id': 'status', 'role': 'status', 'ratio': 0.15, 'priority': 'P0', 'overflow': 'collapse'},
    {'id': 'scene', 'role': 'scene', 'ratio': 0.50, 'priority': 'P0', 'overflow': 'truncate'},
    {'id': 'context', 'role': 'context', 'ratio': 0.20, 'priority': 'P1', 'overflow': 'page'},
    {'id': 'actions', 'role': 'actions', 'ratio': 0.15, 'priority': 'P0', 'overflow': 'collapse'},
]

non_game = {
    'front_page', 'character_creation', 'high_scores', 'rules',
    'rules_character_creation', 'rules_journey', 'rules_scoring', 'credits',
}
game_screens = set()
for path in ui_dir.glob('*.json'):
    original = json.loads(path.read_text())
    if original['id'] not in non_game:
        game_screens.add(original['id'])


def status_controls():
    return [
        {
            'type': 'text', 'id': 'hero_identity', 'frame': 'status',
            'value': '{hero_name} · {hero_class} · Gold: ${cash}',
        },
        {
            'type': 'progressbar', 'id': 'hp_bar', 'frame': 'status',
            'label': 'HP', 'value': '{hp}', 'max': '{max_hp}', 'kind': 'health',
            'thresholds': {'warning': 0.35, 'critical': 0.15}, 'show_text': True,
        },
        {
            'type': 'progressbar', 'id': 'carry_bar', 'frame': 'status',
            'label': 'Carry', 'value': '{total_weight}', 'max': '{max_weight}',
            'kind': 'capacity', 'thresholds': {'warning': 0.8, 'critical': 1.0},
            'show_text': True,
        },
        {
            'type': 'progressbar', 'id': 'journey_bar', 'frame': 'status',
            'label': 'Leg {leg}/5 · Event', 'value': '{event}', 'max': 20,
            'kind': 'journey', 'show_text': True,
        },
    ]


def progress_control(control_id, label, value, maximum, kind, **extra):
    control = {
        'type': 'progressbar', 'id': control_id, 'frame': 'context',
        'label': label, 'value': value, 'max': maximum, 'kind': kind,
        'show_text': True,
    }
    control.update(extra)
    return control


def text_control(value, frame='scene', control_id=None, variant=None):
    control = {'type': 'text', 'frame': frame, 'value': value}
    if control_id:
        control['id'] = control_id
    if variant:
        control['variant'] = variant
    return control

for path in sorted(ui_dir.glob('*.json')):
    original = json.loads(path.read_text())
    screen_id = original['id']
    old_text = original.get('text', [])
    controls = [text_control(original.get('title', screen_id), control_id='screen_title', variant='title')]

    if screen_id in game_screens:
        controls.extend(status_controls())

    if screen_id == 'character_creation':
        controls.append({
            'type': 'input', 'id': 'name_input', 'frame': 'scene',
            'label': 'Hero Name:', 'value': '{pending_name}',
            'placeholder': 'Enter hero name',
        })

    scene_indices = set(range(len(old_text)))
    context_indices = set()
    if screen_id == 'journey':
        scene_indices = {1, 5, 6}
    elif screen_id == 'combat':
        scene_indices = {0}
        context_indices = {1, 2, 3, 4}
    elif screen_id == 'character_sheet':
        scene_indices = {1}
    elif screen_id in {'dungeon_floor_preview', 'dungeon_boss_preview'}:
        scene_indices = {0, 3}
        context_indices = {1, 2}
    elif screen_id == 'super_monster_preview':
        scene_indices = {0, 2}
        context_indices = {1}
    elif screen_id == 'combat_result':
        scene_indices = {0}

    for index, value in enumerate(old_text):
        if index in context_indices:
            controls.append(text_control(value, frame='context'))
        elif index in scene_indices:
            controls.append(text_control(value, frame='scene'))

    if screen_id == 'combat':
        controls[0:0] = []
        controls.extend([
            progress_control('fight_odds', 'Fight', '{fight_win_pct}', 100, 'odds'),
            progress_control('sneak_odds', 'Sneak', '{sneak_win_pct}', 100, 'odds'),
            progress_control('steal_odds', 'Steal', '{steal_win_pct}', 100, 'odds'),
            progress_control('stealth_kill_odds', 'Stealth Kill', '{stealth_kill_win_pct}', 100, 'odds'),
        ])
    elif screen_id in {'dungeon_floor_preview', 'dungeon_boss_preview'}:
        controls.append(progress_control('dungeon_progress', 'Dungeon', '{dungeon_event}', '{dungeon_max}', 'dungeon'))
    elif screen_id == 'level_up':
        controls.append(progress_control('levelup_progress', 'Selected', '{levelup_count}', 3, 'levelup'))
    elif screen_id == 'character_sheet':
        controls.append(progress_control('honor_progress', 'Honor', '{honor_mark}', 15, 'honor'))

    list_limits = {
        'list_inventory': 12,
        'list_character_stats': 8,
        'list_character_equipment': 7,
        'list_rounds': 8,
        'list_scores': 10,
        'list_trader_buy': 5,
        'list_trader_sell': 12,
        'list_houses': 6,
        'list_levelup_skills': 8,
        'loot_lines': 8,
    }
    for list_def in original.get('lists', []):
        control = {
            'type': 'list', 'id': list_def['id'], 'frame': 'context',
            'label': list_def.get('label', ''), 'overflow': 'page',
        }
        if list_def['id'] in list_limits:
            control['max_rows'] = list_limits[list_def['id']]
        controls.append(control)

    for button in original.get('buttons', []):
        control = {'type': 'button', 'frame': 'actions', **button}
        controls.append(control)

    migrated = {'id': screen_id, 'title': original.get('title', screen_id), 'frames': frame_defs, 'controls': controls}
    path.write_text(json.dumps(migrated, indent=2, ensure_ascii=True) + '\n')
